// DecodeError identifies and decodes a declared custom error.
func (c *IDiesisBuybackBurnBinding) DecodeError(raw []byte) (any, error) {
	if len(raw) < 4 {
		return nil, fmt.Errorf("revert payload is shorter than a selector")
	}
	if definition, err := c.customError("BuybackBurnCallFailed()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeBuybackBurnCallFailedError(raw)
	}
	if definition, err := c.customError("UnapprovedAsset()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeUnapprovedAssetError(raw)
	}
	if definition, err := c.customError("WindowAlreadyOpen()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeWindowAlreadyOpenError(raw)
	}
	if definition, err := c.customError("ZeroAmount()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeZeroAmountError(raw)
	}
	return nil, fmt.Errorf("unknown custom error selector %x", raw[:4])
}
